import{_ as n,o as s,c as a,ah as t}from"./chunks/framework.ChH6X6u6.js";const d=JSON.parse('{"title":"Paiements en ligne","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/parent/paiements-en-ligne.md","filePath":"src/guide/parent/paiements-en-ligne.md"}'),r={name:"guide/parent/paiements-en-ligne.md"};function i(o,e,l,u,c,p){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="paiements-en-ligne" tabindex="-1">Paiements en ligne <a class="header-anchor" href="#paiements-en-ligne" aria-label="Permalink to &quot;Paiements en ligne&quot;">​</a></h1><p>Cette page explique comment suivre les frais de scolarité de votre enfant et régler un paiement directement en ligne, sans vous déplacer.</p><h2 id="choisir-les-services-de-l-annee" tabindex="-1">Choisir les services de l&#39;année <a class="header-anchor" href="#choisir-les-services-de-l-annee" aria-label="Permalink to &quot;Choisir les services de l&#39;année&quot;">​</a></h2><p>Sur la fiche de votre enfant, la section <strong>Paiements</strong> présente les <strong>Frais de l&#39;année</strong> :</p><ul><li>les frais <strong>obligatoires</strong> (l&#39;écolage, par exemple), toujours dus ;</li><li>les <strong>services optionnels</strong> proposés par l&#39;établissement (cantine, transport…), chacun avec son prix et une case à cocher.</li></ul><p>Cochez les services que votre enfant prend cette année, puis cliquez sur <strong>Enregistrer mes choix</strong> : le <strong>Total dû</strong> et le <strong>Solde</strong> en tiennent compte aussitôt, et vous pouvez payer.</p><p>Si votre enfant est déjà inscrit pour l&#39;<strong>année suivante</strong> (admission ou réinscription), un second bloc, intitulé par exemple <strong>Année 2027-2028 · 5e A</strong>, apparaît sous celui de l&#39;année en cours, avec ses propres frais, ses services à cocher et son propre bouton de paiement en ligne. Vous pouvez ainsi choisir les services et payer l&#39;inscription avant la rentrée. La page d&#39;accueil de votre espace le signale sur la carte de l&#39;enfant (« Inscrit en 5e A pour 2027-2028 », avec le solde).</p><p>Vous pouvez ajouter un service à tout moment. En revanche, un service marqué <strong>déjà payé</strong> — un paiement a été enregistré depuis que vous l&#39;avez coché — ne peut plus être retiré depuis votre espace : pour l&#39;arrêter, adressez-vous à la caisse de l&#39;établissement. Tant que vous n&#39;avez rien payé, vous pouvez revenir sur vos choix.</p><h2 id="suivre-les-frais-de-scolarite" tabindex="-1">Suivre les frais de scolarité <a class="header-anchor" href="#suivre-les-frais-de-scolarite" aria-label="Permalink to &quot;Suivre les frais de scolarité&quot;">​</a></h2><p>La même section affiche quatre chiffres :</p><ul><li><strong>Total dû</strong> — le montant total des frais pour l&#39;année : les frais obligatoires et les services choisis.</li><li><strong>Remise</strong> — le montant des remises éventuellement accordées.</li><li><strong>Total payé</strong> — ce qui a déjà été réglé, en ligne ou à l&#39;accueil.</li><li><strong>Solde</strong> — ce qu&#39;il reste à payer.</li></ul><p>Si un plan de paiement par tranches a été mis en place, un tableau <strong>Plan de paiement</strong> liste chaque tranche avec son libellé, son montant, sa date d&#39;échéance et son statut (<strong>Payée</strong>, <strong>En retard</strong> ou <strong>À venir</strong>).</p><p>L&#39;historique complet des paiements figure dans un second tableau, avec la date, le montant, la méthode (mobile money, carte bancaire, dépôt bancaire…), l&#39;article de frais concerné et le statut du paiement (<strong>Payé</strong>, <strong>En attente</strong> ou <strong>Échoué</strong>). Cet historique regroupe aussi bien vos paiements en ligne que ceux encaissés directement à l&#39;accueil de l&#39;établissement.</p><h2 id="payer-en-ligne-par-mobile-money" tabindex="-1">Payer en ligne par mobile money <a class="header-anchor" href="#payer-en-ligne-par-mobile-money" aria-label="Permalink to &quot;Payer en ligne par mobile money&quot;">​</a></h2><p>Tant qu&#39;il reste un solde à régler, un bouton <strong>Payer en ligne</strong> apparaît au-dessus des chiffres de paiement — si votre établissement a activé le paiement en ligne. Sans ce bouton, réglez les frais auprès de l&#39;établissement. Pour effectuer un paiement :</p><ol><li>Cliquez sur <strong>Payer en ligne</strong>.</li><li>Dans la fenêtre <strong>Payer par mobile money</strong>, choisissez le <strong>Réseau</strong> à utiliser (Flooz ou Mixx by Yass, ex-T-Money).</li><li>Saisissez le <strong>Numéro de téléphone</strong> qui recevra la demande de paiement.</li><li>Saisissez le <strong>Montant</strong> à payer — il ne peut pas dépasser le solde restant.</li><li>Cliquez sur <strong>Envoyer la demande de paiement</strong>.</li><li>Validez la demande reçue sur votre téléphone via votre opérateur mobile money.</li></ol><p>Le paiement apparaît immédiatement dans l&#39;historique avec le statut <strong>En attente</strong>, puis passe à <strong>Payé</strong> une fois la transaction confirmée. S&#39;il échoue, il apparaît avec le statut <strong>Échoué</strong> et vous pouvez recommencer.</p><h2 id="telecharger-un-recu" tabindex="-1">Télécharger un reçu <a class="header-anchor" href="#telecharger-un-recu" aria-label="Permalink to &quot;Télécharger un reçu&quot;">​</a></h2><p>Une fois un paiement confirmé, un lien <strong>Télécharger le reçu</strong> apparaît en face de celui-ci dans l&#39;historique — cliquez pour obtenir le reçu au format PDF.</p>',19)])])}const m=n(r,[["render",i]]);export{d as __pageData,m as default};
